import {discountedReturn,tdTarget,epsilonPolicy,grid,transition,createQLearner,evaluateGreedy,replayExample,sampleIndices} from './rl-math.js';
const C={lime:'#c5f66a',cyan:'#6bd5d4',orange:'#f4b880',purple:'#b9a1e8',pink:'#eab2c7',grid:'#304332',muted:'#8aa18a'};
const f=n=>(Math.abs(n)<.0005?0:n).toFixed(3);
const text=(g,s,x,y,c=C.muted,size=18,align='center')=>{g.font=`${size}px "DM Sans","Noto Sans SC",sans-serif`;g.fillStyle=c;g.textAlign=align;g.fillText(s,x,y)};
const line=(g,x,y,X,Y,c=C.grid,width=2)=>{g.beginPath();g.moveTo(x,y);g.lineTo(X,Y);g.strokeStyle=c;g.lineWidth=width;g.stroke()};
const dot=(g,x,y,r=6,c=C.lime)=>{g.beginPath();g.arc(x,y,r,0,Math.PI*2);g.fillStyle=c;g.fill()};
const rect=(g,x,y,w,h,c=C.grid)=>{g.fillStyle=c;g.fillRect(x,y,w,h)};
function gridView(g,{pos=12,q=null,path=[],t=0}={}){const sx=37,sy=30,cell=43;for(let i=0;i<16;i++){const x=sx+i%4*cell,y=sy+Math.floor(i/4)*cell,wall=grid.walls.includes(i),pit=grid.pits.includes(i);rect(g,x,y,cell-3,cell-3,wall?'#4b554e':pit?'#553632':i===grid.goal?'#4a6430':'#23372c');if(!wall&&!pit&&i!==grid.goal&&q)text(g,grid.actions[q[i].indexOf(Math.max(...q[i]))],x+20,y+28,C.cyan,21);if(pit)text(g,'×',x+20,y+28,C.pink,25);if(i===grid.goal)text(g,'★',x+20,y+29,C.lime,24)}if(path.length>1)for(let i=1;i<path.length;i++)line(g,sx+path[i-1]%4*cell+20,sy+Math.floor(path[i-1]/4)*cell+20,sx+path[i]%4*cell+20,sy+Math.floor(path[i]/4)*cell+20,C.orange+'77',2);const current=path.length?path[Math.floor(t*3)%path.length]:pos;dot(g,sx+current%4*cell+20,sy+Math.floor(current/4)*cell+20,9,C.lime);text(g,'S',sx+20,sy+3*cell+28,'#c7dfb9',14);}
function bars(g,values,labels,{left=55,width=390,max=1,baseline=192,color=C.cyan}={}){const step=width/values.length;values.forEach((v,i)=>{const h=Math.abs(v)/max*125;rect(g,left+i*step+step*.2,v<0?baseline:baseline-h,step*.56,h,color);text(g,f(v),left+(i+.48)*step,v<0?baseline+h+20:baseline-h-13,color,17);text(g,labels[i],left+(i+.48)*step,229,C.muted,15)})}
export function drawRL(g,id,p,t,mini,state){
switch(id){
case 21:{const s=state.agent??{pos:12,last:null},pos=mini?[12,8,4,0,1,2,3][Math.floor(t*1.5)%7]:s.pos;gridView(g,{pos});const tr=s.last;line(g,250,60,440,60,C.cyan);line(g,440,140,250,140,C.orange);dot(g,250+((t*.3)%1)*190,60,5,C.cyan);text(g,'智能体 → 动作',345,43,C.cyan);text(g,'环境 → 反馈',345,177,C.orange);text(g,mini?'observe · act · reward':`s = ${pos}`,345,108,C.lime,22);return tr?`s=${tr.s}, a=${grid.actions[tr.a]}, r=${f(tr.reward)}, s′=${tr.next}, terminated=${tr.terminated}`:`当前状态 ${pos} · 选择动作后点击“执行动作”`}
case 22:{const gamma=p.gamma??.9,rs=[0,0,1,2],parts=rs.map((r,i)=>r*gamma**i);bars(g,parts,rs.map((r,i)=>`r${i}=${r}`),{max:2,color:C.cyan});line(g,50,193,450,193);const i=Math.floor(t*1.6)%4;dot(g,100+i*97,205,4,C.lime);return `折扣贡献 [${parts.map(f).join(', ')}] · G₀=${f(discountedReturn(rs,gamma))}`}
case 23:{const theta=p.theta??1,right=1/(1+Math.exp(-theta)),prob=[1-right,right];bars(g,prob,['向左','向右'],{color:C.cyan});const choose=((t*.3)%1)<prob[0]?0:1;dot(g,150+choose*195,35,5,C.lime);return `π(左|s)=${f(prob[0])} · π(右|s)=${f(prob[1])} · 概率和 1`}
case 24:{const gamma=p.gamma??.9,values=[gamma**2,gamma,1,0];for(let i=0;i<4;i++){const x=64+i*122;rect(g,x-28,77,56,56,i===3?'#4b6330':'#233d30');text(g,i===3?'终点':`s${i}`,x,112,i===3?C.lime:C.cyan,18);text(g,`V=${f(values[i])}`,x,168,C.lime,17);if(i<3){line(g,x+29,104,x+90,104,C.cyan);text(g,i===2?'+1':'0',x+62,66,C.orange,18)}}dot(g,65+((t*.4)%1)*365,104,4,C.lime);return `V(s₀)=${f(values[0])}, V(s₁)=${f(values[1])}, V(s₂)=1, V(终止)=0`}
case 25:{const epsilon=p.epsilon??.2,ps=epsilonPolicy([.2,.5,.8],epsilon);bars(g,ps,['动作 A','动作 B','动作 C'],{color:C.orange});const u=(t*.3)%1,i=u<ps[0]?0:u<ps[0]+ps[1]?1:2;dot(g,115+i*130,40,6,C.lime);return `ε=${f(epsilon)} · 动作概率 [${ps.map(f).join(', ')}] · C 是当前贪心动作`}
case 26:{const reward=p.reward??1,gamma=p.gamma??.9,terminal=p.terminal==='是',target=tdTarget(reward,gamma,2,terminal),delta=target-1.2;bars(g,[1.2,target],['旧值 V(s)','TD 目标'],{max:4,color:C.purple});text(g,`δ=${f(delta)}`,250,40,delta>=0?C.lime:C.pink,24);dot(g,50+((t*.3)%1)*390,204,4,C.lime);return `目标 = ${f(reward)} ${terminal?'':`+ ${f(gamma)}×2`} = ${f(target)} · TD 误差 δ=${f(delta)}`}
case 27:{const q=state.qlearning??createQLearner(),evaluation=state.evaluation,route=evaluation?.path??q.lastPath;gridView(g,{q:q.q,path:route,t});text(g,'训练回合回报',350,32,C.orange,16);line(g,250,190,465,190);line(g,250,190,250,53);const hist=q.returns.slice(-100);for(let i=1;i<hist.length;i++)line(g,250+(i-1)/Math.max(1,hist.length-1)*215,185-(Math.max(-3.2,hist[i-1])+3.2)/4.2*130,250+i/Math.max(1,hist.length-1)*215,185-(Math.max(-3.2,hist[i])+3.2)/4.2*130,C.orange,2);text(g,`${q.episodes} episodes`,355,217,C.lime,18);return `训练 ${q.episodes} 回合 · 训练成功 ${q.successes} 次${evaluation?` · 冻结策略评估：${evaluation.success?'到达终点':'未到达终点'}，${evaluation.path.length-1} 步，回报 ${f(evaluation.total)}`:' · 点击评估查看当前贪心策略'}`}
case 28:{const count=p.batch??3,ids=sampleIndices(mini?Math.floor(t)+1:state.seed??1,count);for(let i=0;i<8;i++){const x=35+i%4*115,y=35+Math.floor(i/4)*79,tr=replayExample[i],on=ids.includes(i);rect(g,x,y,100,62,on?'#526b35':'#23362b');text(g,`${tr.s} ${grid.actions[tr.a]} ${tr.next}`,x+50,y+25,on?C.lime:C.cyan,18);text(g,`r=${tr.reward}`,x+50,y+48,C.muted,13)}text(g,`8 transitions → batch ${count}`,250,226,C.lime,20);return `无放回采样索引 [${ids.join(', ')}] · 共 ${count} 条转移 · 保留原始终止标志`}
}return ''}
